```java
class Solution {
    public int lcs( String str1, String str2) {
        int n1 = str1.length();
        int n2 = str2.length();
        int[] prev = new int[n2+1];
        int[] curr = new int[n2+1];

        for(int i=0; i<=n1; i++){
            for(int j=0; j<=n2; j++){
                if(i==0 || j==0) curr[j]=0;
                else if(str1.charAt(i-1) == str2.charAt(j-1)){
                    curr[j] = prev[j-1] + 1;
                }else{
                    curr[j] = Math.max(prev[j], curr[j-1]);
                }
            }
            prev = curr;
        }
        return prev[n2];
    }
}


